  ok(swings([bar(0, 1, 1, 1, 1), bar(1, 1, 2, 0.5, 1), bar(2, 1, 1, 1, 1)]).hi[0] === 1 && swings([bar(0, 1, 1, 1, 1), bar(1, 1, 2, 0.5, 1), bar(2, 1, 1, 1, 1)]).lo[0] === 1, '3-bar swings');
