  ok(f.length === 1 && f[0].why === 'target (Monday high)' && Math.abs(f[0].R - (115 - 99.2 - 2 * 0.0992) / (99.2 - 97.2 * 0.995)) < 0.02, 'backtest: one trade, filled at the order block, out at Monday\'s high, ' + (f[0] && f[0].R) + 'R after costs');
